// And groups predicates with the AND operator between them.
func And(predicates ...predicate.BundleDeliveryRollouts) predicate.BundleDeliveryRollouts {
	return predicate.BundleDeliveryRollouts(sql.AndPredicates(predicates...))
}

// Or groups predicates with the OR operator between them.
func Or(predicates ...predicate.BundleDeliveryRollouts) predicate.BundleDeliveryRollouts {
	return predicate.BundleDeliveryRollouts(sql.OrPredicates(predicates...))
}

// Not applies the not operator on the given predicate.
func Not(p predicate.BundleDeliveryRollouts) predicate.BundleDeliveryRollouts {
	return predicate.BundleDeliveryRollouts(sql.NotPredicates(p))
}
